// Castillo del dueño (2026-08-30): pedido por chat dentro de la partida ("genera un snippet que
// construya un castillo y luego ejecutalo para crearlo donde estas ahora").
//
// SEGUNDA VERSIÓN, tras verlo en foto al atardecer. Le dije al dueño lo que le sobraba —«*es todo la
// misma piedra gris y a esta hora se va a negro, se pierde el detalle*»— y me contestó: «*se hace con un
// snippet, mejora el snippet para que quede mas vistoso el castillo y vuelve a generarlo*». Así que el
// arreglo no es tocar la luz (⛔ ver `wiki/paginas/ley-de-la-luz.md`), es que el edificio tenga de qué
// agarrarse cuando la luz se va:
//
//   · TRES piedras y no una: zócalo y sillares de arenisca (clara), muro de ladrillo de piedra, torres de
//     adoquín. Al oscurecer lo que se ve es el CONTRASTE, y con un solo material no hay ninguno.
//   · MUSGO salpicado en la parte baja del muro, sembrado con un hash de la posición: envejece sin que se
//     note el patrón.
//   · VENTANAS ILUMINADAS (saeteras) en muro, torres y torreón. Esto es lo que salva la foto de noche: el
//     castillo deja de ser una mancha negra y pasa a ser una silueta con luces.
//   · SILUETA: torreón central más alto que las torres, tejados cónicos y remates de oro. Un cuadrado
//     liso contra el cielo no dice nada; un perfil escalonado sí.
//   · FOSO CON AGUA en vez de tierra, puente con postes y antorchas, arco de verdad en la puerta y dos
//     estandartes rojos flanqueándola.
//
// Se centra en donde esté quien lo ejecute. Para REHACERLO en el mismo sitio (que es lo que hace falta
// cuando se retoca esto) se le pasa el centro por delante, desde una orden `js`:
//
//     window.CASTILLO_EN = [51, 15, 42]; game.snippet('castillo-del-dueno');
//
// y como lo PRIMERO que hace es vaciar su propia huella, la versión nueva sustituye a la vieja en vez de
// mezclarse con ella.

var o = (typeof opts !== 'undefined' && opts) ? opts : {};

if(o.cfg && o.cfg.nota) window.CASTILLO_EN = [ o.x,o.y,o.z]

const EN = (typeof window !== 'undefined' && Array.isArray(window.CASTILLO_EN)) ? window.CASTILLO_EN : null;
const cx = EN ? Math.round(EN[0]) : Math.round(mc.pos[0]);
const y0 = EN ? Math.floor(EN[1]) : Math.floor(mc.pos[1]);   // el suelo, donde estás parado
const cz = EN ? Math.round(EN[2]) : Math.round(mc.pos[2]);

const N = 17;                                // lado del recinto (impar: centro exacto)
const R = (N - 1) / 2;                       // radio desde el centro a la cara del muro
const H = 7;                                 // alto del muro
const HT = 13;                               // alto de las torres de esquina
const HK = 17;                               // alto del torreón central (manda en la silueta)
const F = 2;                                 // ancho del foso
const ALTO_LIBRE = HK + 8;                   // hasta dónde se vacía antes de construir

// La paleta, en un sitio y con nombre: cambiar el castillo entero es cambiar estas ocho líneas.
const ZOCALO = 'arenisca';                   // clara: es la que dibuja el borde cuando cae el sol
const MURO = 'ladrillo_piedra';
const VIEJO = 'musgo_adoquin';
const TORRE = 'adoquin';
const SILLAR = 'arenisca';
const TEJA = 'tejado';
const VENTANA = 'ventana-iluminada';         // saetera con luz: lo que hace que se vea de noche
const REMATE = 'oro';

// Salpicado estable: mismo bloque siempre en el mismo sitio, sin que se le vea la cuadrícula.
const salpica = (x, y, z, uno_de_cada) => ((x * 73856093 ^ y * 19349663 ^ z * 83492791) >>> 0) % uno_de_cada === 0;

const pon = (dx, dy, dz, mat) => game.setVoxel(cx + dx, y0 + dy, cz + dz, mat);

game.beginBatch();
try {
  // ── 0 · VACIAR LA HUELLA ──────────────────────────────────────────────────────────────────────────
  // Sin esto, rehacer el castillo deja el anterior por debajo y salen dos castillos encajados.
  for (let dx = -R - F; dx <= R + F; dx++)
    for (let dz = -R - F; dz <= R + F; dz++) {
      for (let dy = 0; dy <= ALTO_LIBRE; dy++) pon(dx, dy, dz, 0);
      pon(dx, -1, dz, 'hierba');             // el terreno de vuelta a plano antes de excavar el foso
    }

  // ── 1 · FOSO CON AGUA Y PUENTE ────────────────────────────────────────────────────────────────────
  for (let dx = -R - F; dx <= R + F; dx++)
    for (let dz = -R - F; dz <= R + F; dz++) {
      const fuera = Math.max(Math.abs(dx), Math.abs(dz));
      if (fuera > R && fuera <= R + F) pon(dx, -1, dz, 'agua');
    }
  for (let dz = R + 1; dz <= R + F; dz++)
    for (let dx = -1; dx <= 1; dx++) pon(dx, -1, dz, 'tablones');
  for (const dz of [R + 1, R + F])           // postes con antorcha a los cuatro cantos del puente
    for (const dx of [-2, 2]) { pon(dx, -1, dz, 'tronco'); pon(dx, 0, dz, 'tronco'); pon(dx, 1, dz, 'antorcha'); }

  // ── 2 · EL PATIO ──────────────────────────────────────────────────────────────────────────────────
  for (let dx = -R + 1; dx <= R - 1; dx++)
    for (let dz = -R + 1; dz <= R - 1; dz++) {
      // Camino empedrado de la puerta al torreón; el resto, tablones.
      pon(dx, 0, dz, Math.abs(dx) <= 1 ? 'granito-pulido' : 'tablones');
      // Un jardincillo en las dos esquinas de atrás, para que el patio no sea una tarima vacía.
      if (dz < -2 && Math.abs(dx) > 3 && salpica(dx, 1, dz, 7))
        pon(dx, 1, dz, salpica(dx, 2, dz, 2) ? 'flor-roja' : 'flor-amarilla');
    }

  // ── 3 · LA MURALLA ────────────────────────────────────────────────────────────────────────────────
  const muroDe = (dx, dy, dz) => {
    if (dy <= 1) return ZOCALO;              // zócalo claro: separa el edificio del suelo
    if (dy === H - 1) return ZOCALO;         // cornisa: separa el muro de las almenas
    return (dy <= 3 && salpica(dx, dy, dz, 9)) ? VIEJO : MURO;
  };
  for (let dy = 0; dy < H; dy++) {
    for (let dx = -R; dx <= R; dx++) { pon(dx, dy, -R, muroDe(dx, dy, -R)); pon(dx, dy, R, muroDe(dx, dy, R)); }
    for (let dz = -R; dz <= R; dz++) { pon(-R, dy, dz, muroDe(-R, dy, dz)); pon(R, dy, dz, muroDe(R, dy, dz)); }
  }
  // Saeteras iluminadas, a media altura y cada cuatro bloques.
  for (let d = -R + 2; d <= R - 2; d += 4) {
    pon(d, 4, -R, VENTANA); pon(d, 4, R, VENTANA);
    pon(-R, 4, d, VENTANA); pon(R, 4, d, VENTANA);
  }
  // Almenas: un merlón sí, uno no.
  for (let dx = -R; dx <= R; dx += 2) { pon(dx, H, -R, MURO); pon(dx, H, R, MURO); }
  for (let dz = -R; dz <= R; dz += 2) { pon(-R, H, dz, MURO); pon(R, H, dz, MURO); }

  // ── 4 · LA PUERTA, CON ARCO ───────────────────────────────────────────────────────────────────────
  // Tres de ancho abajo y uno arriba: eso es lo que se lee como arco y no como agujero cuadrado.
  for (let dy = 0; dy <= 2; dy++) for (let dx = -1; dx <= 1; dx++) pon(dx, dy, R, 0);
  pon(0, 3, R, 0);
  for (let dy = 0; dy <= 4; dy++) { pon(-2, dy, R, SILLAR); pon(2, dy, R, SILLAR); }   // jambas
  for (let dx = -2; dx <= 2; dx++) pon(dx, 4, R, SILLAR);                              // dintel
  pon(-1, 3, R, SILLAR); pon(1, 3, R, SILLAR);                                         // riñones del arco
  for (let dy = 5; dy <= 6; dy++) { pon(-3, dy, R, 'red_concrete'); pon(3, dy, R, 'red_concrete'); }  // estandartes

  // ── 5 · LAS CUATRO TORRES DE ESQUINA ──────────────────────────────────────────────────────────────
  for (const [ex, ez] of [[-R, -R], [-R, R], [R, -R], [R, R]]) {
    for (let dy = 0; dy < HT; dy++)
      for (let dx = -1; dx <= 1; dx++)
        for (let dz = -1; dz <= 1; dz++) {
          if (dx === 0 && dz === 0 && dy > 0 && dy < HT - 1) { pon(ex, dy, ez, 0); continue; }  // hueca
          const esquina = dx !== 0 && dz !== 0;   // los cuatro cantos verticales: sillares claros
          pon(ex + dx, dy, ez + dz, dy <= 1 ? ZOCALO : (esquina ? SILLAR : TORRE));
        }
    // Saeteras en las dos caras que dan afuera.
    for (const dy of [5, 9]) { pon(ex + Math.sign(ex), dy, ez, VENTANA); pon(ex, dy, ez + Math.sign(ez), VENTANA); }
    // Corona de almenas y tejado cónico rematado en oro: es lo que le pone perfil al cielo.
    for (let dx = -1; dx <= 1; dx++) for (let dz = -1; dz <= 1; dz++)
      if (dx !== 0 || dz !== 0) pon(ex + dx, HT, ez + dz, SILLAR);
    for (let dx = -1; dx <= 1; dx++) for (let dz = -1; dz <= 1; dz++) pon(ex + dx, HT + 1, ez + dz, TEJA);
    for (let dx = -1; dx <= 1; dx++) for (let dz = -1; dz <= 1; dz++)
      if (Math.abs(dx) + Math.abs(dz) <= 1) pon(ex + dx, HT + 2, ez + dz, TEJA);
    pon(ex, HT + 3, ez, TEJA);
    pon(ex, HT + 4, ez, REMATE);
  }

  // ── 6 · EL TORREÓN CENTRAL ────────────────────────────────────────────────────────────────────────
  // Sin él el castillo es una caja; con él tiene dos alturas y la foto tiene un centro.
  const K = 2;                                 // 5×5
  for (let dy = 0; dy < HK; dy++)
    for (let dx = -K; dx <= K; dx++)
      for (let dz = -K; dz <= K; dz++) {
        const borde = Math.abs(dx) === K || Math.abs(dz) === K;
        if (!borde) { pon(dx, dy, dz, dy === 0 ? 'granito-pulido' : 0); continue; }
        const esquina = Math.abs(dx) === K && Math.abs(dz) === K;
        pon(dx, dy, dz, dy <= 1 ? ZOCALO : (esquina ? SILLAR : MURO));
      }
  for (let dy = 1; dy <= 3; dy++) pon(0, dy, K, 0);                  // su puerta, mirando a la del muro
  pon(0, 4, K, SILLAR);
  for (const dy of [6, 10, 14])                                       // saeteras en las cuatro caras
    for (const s of [-1, 1]) { pon(0, dy, K * s, VENTANA); pon(K * s, dy, 0, VENTANA); }
  for (let dx = -K; dx <= K; dx++) for (let dz = -K; dz <= K; dz++)   // almenas del torreón
    if ((Math.abs(dx) === K || Math.abs(dz) === K) && (dx + dz) % 2 === 0) pon(dx, HK, dz, SILLAR);
  // Y el mástil con la bandera, en el punto más alto de todo.
  for (let dy = HK; dy <= HK + 3; dy++) pon(0, dy, 0, 'tronco');
  pon(0, HK + 4, 0, REMATE);
  for (let dy = HK + 2; dy <= HK + 3; dy++) { pon(1, dy, 0, 'red_concrete'); pon(2, dy, 0, 'red_concrete'); }
} finally {
  game.endBatch();
}

toast('🏰 Castillo levantado en (' + cx + ', ' + y0 + ', ' + cz + ')');
